from collections import defaultdict

from middlewares.errors import ValidationError

STATUS_PENDENTE = "pendente"
STATUS_APROVADO = "aprovado"
STATUS_ENVIADO = "enviado"
STATUS_ENTREGUE = "entregue"
STATUS_CANCELADO = "cancelado"
STATUS_VALIDOS = (STATUS_PENDENTE, STATUS_APROVADO, STATUS_ENVIADO, STATUS_ENTREGUE, STATUS_CANCELADO)

PRODUTO_DESCONHECIDO = "Desconhecido"

ITEMS_WITH_PRODUCT_SQL = """
    SELECT i.pedido_id, i.produto_id, i.quantidade, i.preco_unitario, p.nome AS produto_nome
    FROM itens_pedido i
    LEFT JOIN produtos p ON p.id = i.produto_id
"""


def calculate_total(itens, produtos):
    """Checks that every product exists and has stock; returns the order total."""
    total = 0
    for item in itens:
        produto = produtos.get(item["produto_id"])
        if produto is None:
            raise ValidationError("Produto " + str(item["produto_id"]) + " não encontrado")
        if produto["estoque"] < item["quantidade"]:
            raise ValidationError("Estoque insuficiente para " + produto["nome"])
        total += produto["preco"] * item["quantidade"]
    return total


class OrderModel:
    def __init__(self, get_connection):
        self._db = get_connection

    def create(self, usuario_id, itens, produtos):
        """Persists the order, its items and the stock decrement in one transaction."""
        total = calculate_total(itens, produtos)
        db = self._db()
        with db:
            cursor = db.execute(
                "INSERT INTO pedidos (usuario_id, status, total) VALUES (?, ?, ?)",
                (usuario_id, STATUS_PENDENTE, total),
            )
            pedido_id = cursor.lastrowid
            for item in itens:
                produto_id, quantidade = item["produto_id"], item["quantidade"]
                db.execute(
                    "INSERT INTO itens_pedido (pedido_id, produto_id, quantidade, preco_unitario) VALUES (?, ?, ?, ?)",
                    (pedido_id, produto_id, quantidade, produtos[produto_id]["preco"]),
                )
                updated = db.execute(
                    "UPDATE produtos SET estoque = estoque - ? WHERE id = ? AND estoque >= ?",
                    (quantidade, produto_id, quantidade),
                )
                if updated.rowcount == 0:
                    raise ValidationError("Estoque insuficiente para " + produtos[produto_id]["nome"])
        return {"pedido_id": pedido_id, "total": total}

    def list_all(self):
        pedidos = self._db().execute("SELECT * FROM pedidos").fetchall()
        return self._with_items(pedidos)

    def list_by_user(self, usuario_id):
        pedidos = self._db().execute("SELECT * FROM pedidos WHERE usuario_id = ?", (usuario_id,)).fetchall()
        return self._with_items(pedidos)

    def update_status(self, pedido_id, novo_status):
        db = self._db()
        with db:
            db.execute("UPDATE pedidos SET status = ? WHERE id = ?", (novo_status, pedido_id))

    def count(self):
        return self._db().execute("SELECT COUNT(*) FROM pedidos").fetchone()[0]

    def _with_items(self, pedidos):
        """Loads the items of every order with one JOIN and nests them in the original shape."""
        pedido_ids = [pedido["id"] for pedido in pedidos]
        itens_por_pedido = defaultdict(list)
        if pedido_ids:
            placeholders = ",".join("?" * len(pedido_ids))
            rows = self._db().execute(
                ITEMS_WITH_PRODUCT_SQL + f" WHERE i.pedido_id IN ({placeholders}) ORDER BY i.id", pedido_ids
            ).fetchall()
            for row in rows:
                itens_por_pedido[row["pedido_id"]].append({
                    "produto_id": row["produto_id"],
                    "produto_nome": row["produto_nome"] or PRODUTO_DESCONHECIDO,
                    "quantidade": row["quantidade"],
                    "preco_unitario": row["preco_unitario"],
                })
        return [
            {
                "id": pedido["id"],
                "usuario_id": pedido["usuario_id"],
                "status": pedido["status"],
                "total": pedido["total"],
                "criado_em": pedido["criado_em"],
                "itens": itens_por_pedido[pedido["id"]],
            }
            for pedido in pedidos
        ]

