import logging

from controllers.validators import parse_optional_float, validate_product
from middlewares.errors import ConflictError, NotFoundError

logger = logging.getLogger(__name__)


class ProductController:
    def __init__(self, product_model):
        self._products = product_model

    def list_products(self):
        produtos = self._products.list_all()
        logger.info("Listing %s products", len(produtos))
        return produtos

    def get_product(self, produto_id):
        produto = self._products.get_by_id(produto_id)
        if not produto:
            raise NotFoundError("Produto não encontrado")
        return produto

    def search_products(self, termo, categoria, preco_min, preco_max):
        return self._products.search(
            termo,
            categoria,
            parse_optional_float(preco_min, "preco_min"),
            parse_optional_float(preco_max, "preco_max"),
        )

    def create_product(self, payload):
        produto_id = self._products.create(validate_product(payload))
        logger.info("Product created: id=%s", produto_id)
        return produto_id

    def update_product(self, produto_id, payload):
        self.get_product(produto_id)
        self._products.update(produto_id, validate_product(payload))

    def delete_product(self, produto_id):
        self.get_product(produto_id)
        if self._products.has_order_items(produto_id):
            raise ConflictError("Produto possui pedidos e não pode ser removido")
        self._products.delete(produto_id)
        logger.info("Product deleted: id=%s", produto_id)

