from controllers.validators import validate_login, validate_new_user
from middlewares.errors import NotFoundError, UnauthorizedError
from models.user_model import LOGIN_FIELDS, to_dict

logger = logging.getLogger(__name__)


class UserController:
    def __init__(self, user_model, password_service):
        self._users = user_model
        self._passwords = password_service

    def list_users(self):
        return self._users.list_all()

    def get_user(self, usuario_id):
        usuario = self._users.get_by_id(usuario_id)
        if not usuario:
            raise NotFoundError("Usuário não encontrado")
        return usuario

    def create_user(self, payload):
        nome, email, senha = validate_new_user(payload)
        usuario_id = self._users.create(nome, email, self._passwords.hash_password(senha))
        logger.info("User created: id=%s", usuario_id)
        return usuario_id

    def login(self, payload):
        email, senha = validate_login(payload)
        row = self._users.get_credentials_by_email(email)
        if row is None or not self._passwords.verify_password(row["senha"], senha):
            logger.info("Login failed")
            raise UnauthorizedError("Email ou senha inválidos")
        if not self._passwords.is_hashed(row["senha"]):
            # Legacy plain-text row: upgrade to a real hash after the first successful login
            self._users.update_password_hash(row["id"], self._passwords.hash_password(senha))
        logger.info("Login succeeded: user id=%s", row["id"])
        return to_dict(row, LOGIN_FIELDS)

