from flask import Blueprint, jsonify, request

from middlewares.auth import require_admin_token


def create_product_blueprint(controller):
    bp = Blueprint("produtos", __name__)

    @bp.get("/produtos")
    def listar_produtos():
        return jsonify({"dados": controller.list_products(), "sucesso": True}), 200

    @bp.get("/produtos/busca")
    def buscar_produtos():
        resultados = controller.search_products(
            request.args.get("q", ""),
            request.args.get("categoria"),
            request.args.get("preco_min"),
            request.args.get("preco_max"),
        )
        return jsonify({"dados": resultados, "total": len(resultados), "sucesso": True}), 200

    @bp.get("/produtos/<int:produto_id>")
    def buscar_produto(produto_id):
        return jsonify({"dados": controller.get_product(produto_id), "sucesso": True}), 200

    @bp.post("/produtos")
    @require_admin_token
    def criar_produto():
        produto_id = controller.create_product(request.get_json(silent=True))
        return jsonify({"dados": {"id": produto_id}, "sucesso": True, "mensagem": "Produto criado"}), 201

    @bp.put("/produtos/<int:produto_id>")
    @require_admin_token
    def atualizar_produto(produto_id):
        controller.update_product(produto_id, request.get_json(silent=True))
        return jsonify({"sucesso": True, "mensagem": "Produto atualizado"}), 200

    @bp.delete("/produtos/<int:produto_id>")
    @require_admin_token
    def deletar_produto(produto_id):
        controller.delete_product(produto_id)
        return jsonify({"sucesso": True, "mensagem": "Produto deletado"}), 200

    return bp

