from controllers.validators import validate_order, validate_status


class OrderController:
    def __init__(self, order_model, product_model, notification_service):
        self._orders = order_model
        self._products = product_model
        self._notifications = notification_service

    def create_order(self, payload):
        usuario_id, itens = validate_order(payload)
        produtos = self._products.get_many([item["produto_id"] for item in itens])
        resultado = self._orders.create(usuario_id, itens, produtos)
        self._notifications.order_created(resultado["pedido_id"], usuario_id)
        return resultado

    def list_orders(self):
        return self._orders.list_all()

    def list_user_orders(self, usuario_id):
        return self._orders.list_by_user(usuario_id)

    def update_status(self, pedido_id, payload):
        novo_status = validate_status(payload)
        self._orders.update_status(pedido_id, novo_status)
        self._notifications.order_status_changed(pedido_id, novo_status)
